# Let me use a flood fill from outside to find "outside" 6s
# Any 6s not reachable from outside by going through 6s are "inside"

from collections import deque

def flood_from_outside(grid, shape_color):
    """Find all 6-cells that are reachable from the edge of the grid"""
    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    queue = deque()

    # Add all cells on the edge to the queue
    for r in range(rows):
        for c in range(cols):
            if (r == 0 or r == rows-1 or c == 0 or c == cols-1) and grid[r][c] == 6:
                visited.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:  # 4-connectivity
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == 6:
                    visited.add((nr, nc))
                    queue.append((nr, nc))

    return visited

